# Every game owns one cancellable timer; old callbacks cannot restart a reset game.
def game_pause(app):
    app.running = False
    app.generation += 1
    if app.timer is not None:
        app.root.after_cancel(app.timer)
        app.timer = None

def game_tick(app, generation):
    if not app.running or generation != app.generation:
        return
    app.timer = None
    game_step(app)
    game_draw(app)
    if app.running and generation == app.generation:
        app.timer = app.root.after(60, lambda: game_tick(app, generation))

def game_start(app):
    if app.running or app.over:
        return
    app.running = True
    app.generation += 1
    app.Board.focus_set()
    game_tick(app, app.generation)

def game_close(app):
    game_pause(app)
    app.root.destroy()

# This original map uses grid coordinates and breadth-first pursuit.
from collections import deque
MAZE = ('###############', '#.............#', '#.###.###.###.#', '#...#.....#...#', '#.#.#.###.#.#.#', '#.#.........#.#', '#.###.#.#.###.#', '#.....#.#.....#', '#.###.....###.#', '#.............#', '###############')

def maze_neighbors(cell):
    x, y = cell
    return [(a,b) for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)) if 0 <= b < len(MAZE) and 0 <= a < len(MAZE[0]) and MAZE[b][a] != '#']

def chase_next(start, target):
    queue = deque([(start, [])]); seen = {start}
    while queue:
        cell, path = queue.popleft()
        if cell == target:
            return path[0] if path else start
        for neighbor in maze_neighbors(cell):
            if neighbor not in seen:
                seen.add(neighbor); queue.append((neighbor, path + [neighbor]))
    return start

def game_reset(app):
    game_pause(app)
    app.player = (1,1); app.enemy = (13,9); app.intent = (0,0); app.frames = 0
    app.dots = {(x,y) for y,row in enumerate(MAZE) for x,char in enumerate(row) if char == '.'} - {app.player}
    app.score = 0; app.over = False
    game_draw(app)

def chase_turn(app, dx, dy):
    if app.running:
        app.intent = (dx,dy)

def game_step(app):
    app.frames += 1
    if app.frames % 3:
        return
    x,y = app.player; dx,dy = app.intent; target = (x+dx,y+dy)
    if target in maze_neighbors(app.player):
        app.player = target
    if app.player in app.dots:
        app.dots.remove(app.player); app.score += 1
    caught = app.player == app.enemy
    if app.frames % 6 == 0 and not caught:
        app.enemy = chase_next(app.enemy, app.player)
    app.over = caught or app.player == app.enemy or not app.dots
    if app.over:
        game_pause(app)

def game_draw(app):
    c = app.Board; c.delete('all'); size = 38
    for y,row in enumerate(MAZE):
        for x,char in enumerate(row):
            if char == '#':
                c.create_rectangle(x*size,y*size,(x+1)*size,(y+1)*size,fill='#344b80',outline='')
    for x,y in app.dots:
        c.create_oval(x*size+16,y*size+16,x*size+22,y*size+22,fill='#fff1a6',outline='')
    for cell,color in ((app.player,'#ffca55'),(app.enemy,'#ff7187')):
        x,y = cell; c.create_oval(x*size+5,y*size+5,(x+1)*size-5,(y+1)*size-5,fill=color)
    outcome = ('All dots collected!' if not app.dots else 'Caught! Reset to retry.') if app.over else 'Arrow keys: collect dots, avoid the pursuer.'
    app.Status.configure(text=f'Dots: {app.score} | {outcome}')
